import java.util.*;

public class TextDoc {

    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int n = scan.nextInt();
        scan.nextLine();
        String s = scan.nextLine();

        // Process string using StringBuilder to extract parenthetical content
        List<String> parenContents = new ArrayList<>();
        StringBuilder current = new StringBuilder();
        boolean inside = false;

        for (char c : s.toCharArray()) {
            if (c == '(') {
                inside = true;
                current.setLength(0);
            } else if (c == ')' && inside) {
                parenContents.add(current.toString());
                inside = false;
            } else if (inside) {
                current.append(c);
            }
        }

        // Find maximum word length and count non-empty words
        int maxLen = 0;
        int wordCount = 0;

        for (String content : parenContents) {
            String[] words = content.split("_");
            for (String word : words) {
                if (!word.isEmpty()) {
                    maxLen = Math.max(maxLen, word.length());
                    wordCount++;
                }
            }
        }

        System.out.println(maxLen + " " + wordCount);
    }
}
